package me.cryo.zombierool.scripting;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraftforge.network.*;
import java.util.*;
import java.util.function.Supplier;
public final class LuaWorkbenchPackets {
 public record Request(String action,String name,String code,String version){public static void encode(Request p,FriendlyByteBuf b){b.writeUtf(p.action,32);b.writeUtf(p.name,80);b.writeUtf(p.code,1000000);b.writeUtf(p.version,64);}public static Request decode(FriendlyByteBuf b){return new Request(b.readUtf(32),b.readUtf(80),b.readUtf(1000000),b.readUtf(64));}public static void handle(Request p,Supplier<NetworkEvent.Context> c){c.get().enqueueWork(()->{var player=c.get().getSender();if(player==null||!player.hasPermissions(2))return;var result=LuaWorkbench.request(player,p.action,p.name,p.code,p.version);me.cryo.zombierool.network.NetworkHandler.INSTANCE.send(PacketDistributor.PLAYER.with(()->player),new Response(result));});c.get().setPacketHandled(true);}}
 public record Response(net.minecraft.nbt.CompoundTag data){public static void encode(Response p,FriendlyByteBuf b){b.writeNbt(p.data);}public static Response decode(FriendlyByteBuf b){return new Response(b.readNbt());}public static void handle(Response p,Supplier<NetworkEvent.Context> c){c.get().enqueueWork(()->net.minecraftforge.fml.DistExecutor.unsafeRunWhenOn(net.minecraftforge.api.distmarker.Dist.CLIENT,()->()->{Client.receive(p.data);}));c.get().setPacketHandled(true);}}
 @net.minecraftforge.api.distmarker.OnlyIn(net.minecraftforge.api.distmarker.Dist.CLIENT)
 private static final class Client {static void receive(net.minecraft.nbt.CompoundTag data){var mc=net.minecraft.client.Minecraft.getInstance();if(data.getString("action").equals("actor_catalogue")){me.cryo.zombierool.client.MapActorCatalogue.accept(data.getCompound("names"),data.getCompound("nameKeys"),data.getCompound("eggVariants"));return;}if(data.getString("action").equals("actor_open_catalog"))mc.setScreen(new me.cryo.zombierool.client.gui.MapActorStudioScreen(null,null));else if(data.getString("action").equals("actor_open"))mc.setScreen(new me.cryo.zombierool.client.gui.MapActorStudioScreen(null,net.minecraft.core.BlockPos.of(data.getLong("pos"))));else if(mc.screen instanceof me.cryo.zombierool.client.gui.MapActorStudioScreen studio)studio.response(data);else if(mc.screen instanceof me.cryo.zombierool.client.gui.LuaWorkbenchScreen screen)screen.response(data);}}
 public static void register(net.minecraftforge.network.simple.SimpleChannel channel,int id){channel.registerMessage(id,Request.class,Request::encode,Request::decode,Request::handle,Optional.of(NetworkDirection.PLAY_TO_SERVER));channel.registerMessage(id+1,Response.class,Response::encode,Response::decode,Response::handle,Optional.of(NetworkDirection.PLAY_TO_CLIENT));}
}
